def compute(vars):
    receivables = vars["v1"]
    payables = vars["v2"]
    if payables == 0:
        return None
    ratio = receivables / payables
    return {
        "value": ratio,
        "trace": {
            "receivables": receivables,
            "payables": payables,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
